  function applyLanguage(){const en=language==='en';document.documentElement.lang=en?'en':'zh-CN';document.title=(document.body.dataset.page==='creator'?(en?'Contributor workspace · Fang123':'创作者工作台 · Fang123 视觉演示'):document.body.dataset.page==='article'?(en?'When home prices fall, why might the payment stay the same? · Fang123':'房价降了，为什么月供未必减少？ · Fang123'):(en?'Fang123 Real Estate Market Monitor · Visual prototype':'Fang123 房市观察 · 视觉演示')); $$('[data-language]').forEach(b=>{b.textContent=en?'中':'EN';b.setAttribute('aria-label',en?'切换到中文':'Switch to English');});const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode()){const parent=node.parentElement;if(!parent||parent.closest('script,style,svg'))continue;const raw=originalTextNodes.get(node)??node.nodeValue,trimmed=raw.trim();if(languagePairs[trimmed]){originalTextNodes.set(node,raw);const prefix=raw.slice(0,raw.indexOf(trimmed)),suffix=raw.slice(raw.indexOf(trimmed)+trimmed.length);node.nodeValue=prefix+(en?languagePairs[trimmed]:trimmed)+suffix;}}$$('body *').forEach(el=>{for(const a of ['placeholder','aria-label','title','alt','label']){const v=el.getAttribute?.(a),key=a.replace(/-([a-z])/g,(_,c)=>c.toUpperCase());if(v&&languagePairs[v]){if(!el.dataset['original'+key]){el.dataset['original'+key]=v;el.dataset['en'+key]=languagePairs[v];}el.setAttribute(a,en?el.dataset['en'+key]:el.dataset['original'+key]);}}});}
