  function renderLenders(){const type=$('#rateType')?.value||'fixed',en=language==='en';if(!$('#lenderRows'))return;const kinds={'Major bank':'大型银行','Credit union network':'信用合作社网络','Ontario credit union':'安省信用合作社','Credit union':'信用合作社','Mortgage lender':'按揭贷款机构'},notes={'Special offer':'特别优惠','Smart Fixed offer':'Smart Fixed 优惠','Official rate page':'官方利率页面','Check current offers':'查看当日报价'};$('#lenderRows').innerHTML=lenders.map(l=>`<tr><td><b>${l.name}</b><small>${en?l.kind:kinds[l.kind]}</small></td><td>${en?'5-year '+(type==='fixed'?'fixed':'variable'):(type==='fixed'?'5 年固定':'5 年浮动')}</td><td class="rate-number">${type==='fixed'?l.fixed:l.variable}<small>${en?l.note:notes[l.note]}</small></td><td><a href="${l.url}" target="_blank" rel="noopener">${en?'View source':'查看来源'} ↗</a></td></tr>`).join('');}
