  function calculateMortgage(){const price=Number($('#homePrice')?.value)||0,down=Number($('#downPayment')?.value)||0,annual=Number($('#calcRate')?.value)||0,years=Number($('#amortization')?.value)||25,principal=Math.max(0,price-down),r=Math.pow(1+annual/200,1/6)-1,n=years*12,payment=r===0?principal/n:principal*r*Math.pow(1+r,n)/(Math.pow(1+r,n)-1);if($('#paymentAmount'))$('#paymentAmount').textContent=principal>0?new Intl.NumberFormat(language==='en'?'en-CA':'zh-CN',{style:'currency',currency:'CAD',maximumFractionDigits:0}).format(payment):'—';}
